#ifdef EMBEDDED_FREESTANDING
static inline float expf_fast(float x) {
    if (x < -16.0f) return 0.0f;
    float sum = 1.0f + x * (1.0f + x * (0.5f + x * (0.16666667f + x * 0.04166667f)));
    return sum > 0.0f ? sum : 0.0f;
}
#define exp(x) expf_fast(x)
#endif

