void ids_predict_logits(const float features[IDS_NUM_FEATURES], float logits[IDS_NUM_CLASSES]) {
    logits[0] = eval_class_0(features);
    logits[1] = eval_class_1(features);
    logits[2] = eval_class_2(features);
    logits[3] = eval_class_3(features);
    logits[4] = eval_class_4(features);
    logits[5] = eval_class_5(features);
    logits[6] = eval_class_6(features);
    logits[7] = eval_class_7(features);
    logits[8] = eval_class_8(features);
    logits[9] = eval_class_9(features);
}

int ids_predict(const float features[IDS_NUM_FEATURES]) {
    float logits[IDS_NUM_CLASSES];
    ids_predict_logits(features, logits);
    int best_class = 0;
    float max_score = logits[0];
    for (int i = 1; i < IDS_NUM_CLASSES; i++) {
        if (logits[i] > max_score) {
            max_score = logits[i];
            best_class = i;
        }
    }
    return best_class;
}

void ids_predict_proba(const float features[IDS_NUM_FEATURES], float proba[IDS_NUM_CLASSES]) {
    float logits[IDS_NUM_CLASSES];
    ids_predict_logits(features, logits);
    float max_score = logits[0];
    for (int i = 1; i < IDS_NUM_CLASSES; i++) {
        if (logits[i] > max_score) max_score = logits[i];
    }
    float sum_exp = 0.0f;
    for (int i = 0; i < IDS_NUM_CLASSES; i++) {
        proba[i] = (float)exp(logits[i] - max_score);
        sum_exp += proba[i];
    }
    for (int i = 0; i < IDS_NUM_CLASSES; i++) {
        proba[i] /= (sum_exp > 0.0f ? sum_exp : 1.0f);
    }
}

const char* ids_get_class_name(int class_index) {
    if (class_index >= 0 && class_index < IDS_NUM_CLASSES) {
        return IDS_CLASS_NAMES[class_index];
    }
    return "UNKNOWN";
}
